+/* ── Reset & tokens ─────────────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --color-bg:           #f5f6fa;
+  --color-surface:      #ffffff;
+  --color-border:       #d1d5db;
+  --color-border-focus: #4f46e5;
+  --color-border-error: #dc2626;
