+  --color-primary:      #4f46e5;
+  --color-primary-dark: #3730a3;
+  --color-primary-text: #ffffff;
+  --color-required:     #b91c1c;
+  --radius:             0.5rem;
+  --shadow:             0 4px 24px 0 rgba(0,0,0,.08);
+  --transition:         0.15s ease;
