+/* ── Base ───────────────────────────────────────────── */
+body {
+  font-family: 'Inter', system-ui, -apple-system, sans-serif;
+  background: var(--color-bg);
+  color: var(--color-text);
+  min-height: 100vh;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  padding: 2rem 1rem;
+}
+
+/* ── Skip link ──────────────────────────────────────── */
+.skip-link {
+  position: absolute;
+  top: -3rem;
+  left: 1rem;
+  background: var(--color-primary);
+  color: var(--color-primary-text);
+  padding: 0.5rem 1rem;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; outline: 3px solid var(--color-primary-dark); outline-offset: 2px; }
+
+/* ── Page header ────────────────────────────────────── */
+header {
+  text-align: center;
+  margin-bottom: 2rem;
+}
+header .brand {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-primary);
+  letter-spacing: -0.01em;
+  margin-bottom: 0.25rem;
+}
+
+/* ── Card ───────────────────────────────────────────── */
+main {
+  width: 100%;
+  max-width: 520px;
+}
+.card {
+  background: var(--color-surface);
+  border-radius: calc(var(--radius) * 2);
+  box-shadow: var(--shadow);
+  padding: 2.5rem 2rem;
+}
+@media (max-width: 400px) { .card { padding: 1.5rem 1rem; } }
+
+.card-header { margin-bottom: 2rem; }
+.card-header h1 {
+  font-size: 1.5rem;
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  line-height: 1.2;
+  color: var(--color-text);
+}
+.card-header p {
+  margin-top: 0.4rem;
+  color: var(--color-text-muted);
+  font-size: 0.9375rem;
+  line-height: 1.5;
+}
+
+/* ── Form fields ────────────────────────────────────── */
+.form-fields { display: flex; flex-direction: column; gap: 1.25rem; }
+
+.form-field { display: flex; flex-direction: column; gap: 0.375rem; }
+
+.form-field label {
+  font-size: 0.875rem;
+  font-weight: 600;
