+/**
+ * ContactForm — React-style component logic for the support contact form.
+ * Runs entirely in vanilla JS; no build step required.
+ */
+
+(function ContactForm() {
+  /* ── Field descriptors ─────────────────────────────── */
+  const FIELDS = [
+    {
+      id: 'full-name',
+      required: true,
+      validate(value) {
+        if (!value.trim()) return 'Please enter your full name.';
+        return null;
+      },
+    },
+    {
+      id: 'email',
+      required: true,
+      validate(value) {
+        if (!value.trim()) return 'Please enter your email address.';
+        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
+          return 'Please enter a valid email address (e.g. you@example.com).';
+        return null;
+      },
+    },
+    {
+      id: 'phone',
+      required: false,
+      validate(value) {
+        if (!value.trim()) return null; // optional
+        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
+          return 'Please enter a valid phone number in the format shown below.';
+        return null;
+      },
+    },
+  ];
+
+  /* ── State ─────────────────────────────────────────── */
+  // Track whether a field has been "touched" (blurred or submit attempted)
+  const touched = {};
+  FIELDS.forEach(f => (touched[f.id] = false));
+
+  /* ── Helpers ───────────────────────────────────────── */
+  function getInput(id)   { return document.getElementById(id); }
+  function getError(id)   { return document.getElementById(`${id}-error`); }
+
+  function showError(field, message) {
+    const input = getInput(field.id);
+    const error = getError(field.id);
+    if (!input || !error) return;
+    input.setAttribute('aria-invalid', 'true');
+    error.textContent = message;
+    error.setAttribute('data-visible', 'true');
+  }
+
+  function clearError(field) {
+    const input = getInput(field.id);
+    const error = getError(field.id);
+    if (!input || !error) return;
+    input.removeAttribute('aria-invalid');
+    error.textContent = '';
+    error.setAttribute('data-visible', 'false');
+  }
+
+  function validateField(field) {
+    const input = getInput(field.id);
+    if (!input) return null;
+    const message = field.validate(input.value);
+    if (message) {
+      showError(field, message);
+    } else {
+      clearError(field);
+    }
+    return message;
+  }
+
+  /* ── Live validation on blur ───────────────────────── */
+  function attachBlurListeners() {
+    FIELDS.forEach(field => {
+      const input = getInput(field.id);
+      if (!input) return;
+      input.addEventListener('blur', () => {
+        touched[field.id] = true;
+        validateField(field);
+      });
+      // Re-validate on input only after first touch
+      input.addEventListener('input', () => {
+        if (touched[field.id]) validateField(field);
