+      statusBanner.setAttribute('data-type', 'error');
+      statusBanner.textContent = 'Please fix the errors below before submitting.';
+      statusBanner.setAttribute('data-visible', 'true');
+      return;
+    }
+
+    // Success path — simulate submission
+    statusBanner.setAttribute('data-type', 'success');
+    statusBanner.textContent = "Thanks! We've received your message and will be in touch shortly.";
+    statusBanner.setAttribute('data-visible', 'true');
+    statusBanner.focus();
+
+    // Reset form
+    e.target.reset();
+    FIELDS.forEach(f => {
+      touched[f.id] = false;
+      clearError(f);
+    });
+  }
