+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  transition: top var(--transition);
+}
+.skip-link:focus { top: 1rem; outline: 3px solid var(--color-primary-dark); outline-offset: 2px; }
+
+/* ── Page header ────────────────────────────────────── */
+header {
