+  margin-bottom: 1.25rem;
+}
+.status-banner[data-visible="true"] { display: block; }
+.status-banner[data-type="success"] {
+  background: #dcfce7;
+  color: #166534;
+  border: 1.5px solid #86efac;
+}
+.status-banner[data-type="error"] {
+  background: #fef2f2;
+  color: #991b1b;
+  border: 1.5px solid #fca5a5;
+}
+
+/* ── Forced colors ──────────────────────────────────── */
+@media (forced-colors: active) {
+  .form-field input { border: 2px solid ButtonText; }
+  .form-field input:focus { outline: 3px solid Highlight; }
+  .submit-btn { border: 2px solid ButtonBorder; forced-color-adjust: none; background: ButtonFace; color: ButtonText; }
